// real CMS SignedData (EC-signed SOD payload), same sample used by cms.FuzzParseSignedData
var fuzzSodSignedDataBytes = utils.HexToBytes("")

// valid EF.SOD: SODTag (0x77) wrapping fuzzSodSignedDataBytes
var fuzzSodBytes = tlv.NewTlvSimpleNode(SODTag, fuzzSodSignedDataBytes).Encode()

// valid EF.COM (from 9303-p10), same sample used by document CBOR tests
var fuzzComBytes = utils.HexToBytes("60145F0104303130365F36063034303030305C026175")

var fuzzCardAccessBytes = utils.HexToBytes("31283012060a04007f0007020204020202010202010d3012060a04007f0007020204060202010202010d")

var fuzzEfDirBytes = utils.HexToBytes("61094F07A000000247100161094F07A000000247200161094F07A000000247200261094F07A0000002472003")

// valid DG1 (MRZ), same sample used by document CBOR tests
var fuzzDg1Bytes = utils.HexToBytes("614B5F1F48493C55544F4552494B53534F4E3C3C414E4E413C4D415249413C3C3C3C3C3C3C3C3C3C3C4432333134353839303755544F3734303831323246313230343135393C3C3C3C3C3C3C36")

var fuzzDg2Bytes = utils.HexToBytes("75067f6103020101")

// minimal DG7: 1 image, a 5-byte JPEG-magic-prefixed "image" (0x67 = DG7, 0x02 = count, 0x5F43 = image)
var fuzzDg7Bytes = utils.HexToBytes("670B0201015F4305FFD8FF0102")

var fuzzDg11Bytes = utils.HexToBytes("6B605C0A5F0E5F115F425F125F135F0E0D534D4954483C3C4A4F484E3C4A5F110A414E59544F574E3C4D4E5F4217313233204D41504C452052443C414E59544F574E3C4D4E5F120B31363132353535313231325F130C54524156454C3C4147454E54")

var fuzzDg12Bytes = utils.HexToBytes("6C3E5C045F195F265F192A4A414B41525441202D20414D42415353414445204445204652414E434520454E20494E444F4E455349455F26083230313730393035")

var fuzzDg13Bytes = utils.HexToBytes("6D0A01234567890123456789")

var fuzzDg14Bytes = utils.HexToBytes("")

var fuzzDg15Bytes = utils.HexToBytes("")

var fuzzDg16Bytes = utils.HexToBytes("")

func FuzzNewCOM(f *testing.F) {
	f.Add([]byte(nil))
	f.Add(utils.HexToBytes("55021234"))
	f.Add(fuzzComBytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = NewCOM(data)
	})
}

