func FuzzNewDocumentFromCbor(f *testing.F) {
	var doc Document
	doc.Mf.Lds1.Dg1, _ = NewDG1(fuzzDg1Bytes)
	if cborBytes, err := doc.ToCbor(); err == nil {
		f.Add(cborBytes)
	}

	f.Add([]byte(nil))

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = NewDocumentFromCbor(data)
	})
}

func FuzzNewChipAuthEvidenceFromCbor(f *testing.F) {
	var session Session
	if cborBytes, err := session.ChipAuthEvidenceToCbor(); err == nil {
		f.Add(cborBytes)
	}

	f.Add([]byte(nil))

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = NewChipAuthEvidenceFromCbor(data)
	})
}

func FuzzNewDG(f *testing.F) {
	f.Add(1, fuzzDg1Bytes)
	f.Add(2, fuzzDg2Bytes)
	f.Add(2, dg2AllFields39794)
	f.Add(7, fuzzDg7Bytes)
	f.Add(11, fuzzDg11Bytes)
	f.Add(12, fuzzDg12Bytes)
	f.Add(13, fuzzDg13Bytes)
	f.Add(14, fuzzDg14Bytes)
	f.Add(15, fuzzDg15Bytes)
	f.Add(16, fuzzDg16Bytes)
	f.Add(0, []byte(nil))
	f.Add(3, []byte{0x01, 0x02})

	f.Fuzz(func(t *testing.T, dg int, data []byte) {
		var doc Document
		_ = doc.NewDG(dg, data)
	})
}

func FuzzNewDG1(f *testing.F) {
	f.Add([]byte(nil))
	f.Add(utils.HexToBytes("6109010212340203123456"))
	f.Add(fuzzDg1Bytes)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = NewDG1(data)
	})
}

func FuzzNewDG2(f *testing.F) {
	f.Add([]byte(nil))
	f.Add(utils.HexToBytes("7500"))
	f.Add(fuzzDg2Bytes)
	// fuzzDg2Bytes above is too shallow to reach the nested ISO19794/ISO39794
	// biometric-image parsers (dg2.go calls them on the BIT/BHT-wrapped data);
	// these real samples (already used by document's own DG2 tests) do.
	f.Add(dg2AllFields39794)
	f.Add(dg2MandFields39794)

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _ = NewDG2(data)
	})
}

